"use client";
import { useState, useEffect } from 'react';
import axios from 'axios';
import Link from 'next/link';
import { IconButton } from '@mui/material';
import { Edit as EditIcon, Delete as DeleteIcon, Search as SearchIcon, ArrowBack as ArrowBackIcon } from '@mui/icons-material';
import Sidebar from '../components/sidebar'; 
import Navbar from '../components/Navbar';

export default function GestionGroupes() {
  const [etudiants, setEtudiants] = useState([]);
  const [selectedEtudiants, setSelectedEtudiants] = useState([]);
  const [groupes, setGroupes] = useState([]);
  const [showGroupes, setShowGroupes] = useState(false);
  const [groupeType, setGroupeType] = useState('alphabet');
  const [showGenerateForm, setShowGenerateForm] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(20); // Afficher 20 éléments par page

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [etudiantsResponse, groupesResponse] = await Promise.all([
        axios.get('http://localhost:5000/api/etudiants'),
        axios.get('http://localhost:5000/api/groupes')
      ]);

      const groupesMap = new Map(groupesResponse.data.map(g => [g.idGroupe, g.nomGroupe]));
      const etudiantsAvecGroupes = etudiantsResponse.data.map(etudiant => ({
        ...etudiant,
        nomGroupe: groupesMap.get(etudiant.idGroupe) || "-"
      }));

      setEtudiants(etudiantsAvecGroupes);
      setGroupes(groupesResponse.data);
    } catch (err) {
      console.error("Erreur lors de la récupération des données :", err);
    }
  };

  const trierEtudiants = (etudiants) => {
    return etudiants.sort((a, b) => {
      if (a.idGroupe && b.idGroupe) {
        return a.idGroupe - b.idGroupe;
      } else if (a.idGroupe) {
        return -1;
      } else if (b.idGroupe) {
        return 1;
      } else {
        return 0;
      }
    });
  };

  const toggleSelection = (id) => {
    setSelectedEtudiants((prevSelected) =>
      prevSelected.includes(id)
        ? prevSelected.filter((etudiantId) => etudiantId !== id)
        : [...prevSelected, id]
    );
  };

  const genererGroupe = async () => {
    if (selectedEtudiants.length === 0) {
      alert("Veuillez sélectionner des étudiants.");
      return;
    }
    try {
      await axios.post('http://localhost:5000/api/ajouterGroupe', { 
        etudiants: selectedEtudiants,
        groupeType: groupeType
      });
      alert("Groupe créé avec succès");
      setSelectedEtudiants([]);
      setShowGenerateForm(false);
      fetchData();
    } catch (err) {
      console.error("Erreur lors de la création du groupe :", err);
      alert("Erreur lors de la création du groupe");
    }
  };

  const deleteGroupe = async (idGroupe) => {
    if (!window.confirm("Voulez-vous vraiment supprimer ce groupe et ses étudiants ?")) return;
    try {
      await axios.delete(`http://localhost:5000/api/supprimerGroupe/${idGroupe}`);
      alert("Groupe supprimé avec succès");
      fetchData();
    } catch (err) {
      console.error("Erreur lors de la suppression du groupe :", err);
      alert("Erreur lors de la suppression du groupe");
    }
  };

  const filteredEtudiants = etudiants.filter((etudiant) => 
    etudiant.nom.toLowerCase().includes(searchQuery.toLowerCase()) ||
    etudiant.prenom.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentEtudiants = filteredEtudiants.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(filteredEtudiants.length / itemsPerPage);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  const handleItemsPerPageChange = (e) => {
    setItemsPerPage(Number(e.target.value));
    setCurrentPage(1);
  };

  const etudiantsTries = trierEtudiants(currentEtudiants);

  return (
    <div className="flex h-screen min-h-screen w-screen bg-gradient-to-r from-blue-50 to-gray-50">
      <Sidebar className="h-screen hidden lg:block" />
      <div className="w-full flex flex-col h-screen">
        <Navbar />
        <div className="w-full flex-1 py-5 px-6 overflow-y-auto"> {/* Scroll sur la page entière */}
          {/* Afficher les boutons uniquement si on n'est pas en mode "Voir les Groupes" */}
          {!showGroupes && (
            <div className="mb-6 space-x-4">
              {!showGenerateForm ? (
                <button 
                  onClick={() => setShowGenerateForm(true)} 
                  className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-500 transition duration-300 transform hover:scale-105 shadow-lg"
                >
                  Générer Groupe
                </button>
              ) : (
                <div className="mb-4 space-y-2 bg-white p-6 rounded-lg shadow-lg border border-gray-200 w-1/3"> {/* Formulaire plus petit et aligné à gauche */}
                  <select
                    value={groupeType}
                    onChange={(e) => setGroupeType(e.target.value)}
                    className="border p-2 rounded-md focus:outline-none shadow-sm w-full"
                  >
                    <option value="alphabet">Groupe alphabétique</option>
                    <option value="numerique">Groupe numérique</option>
                  </select>
                  <div className="flex space-x-2">
                    <button 
                      onClick={genererGroupe} 
                      className="bg-blue-500 text-white px-4 py-2 rounded-lg hover:bg-blue-600 transition duration-300 transform hover:scale-105"
                    >
                      Confirmer la création
                    </button>
                    <button 
                      onClick={() => setShowGenerateForm(false)} 
                      className="bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 transition duration-300 transform hover:scale-105"
                    >
                      Annuler
                    </button>
                  </div>
                </div>
              )}
              <button 
                onClick={() => setShowGroupes(!showGroupes)} 
                className="bg-blue-500 text-white px-6 py-3 rounded-lg hover:bg-blue-600 transition duration-300 transform hover:scale-105 shadow-lg"
              >
                {showGroupes ? 'Voir les Étudiants' : 'Voir les Groupes'}
              </button>
            </div>
          )}

          {/* Barre de recherche */}
          <div className="relative w-full sm:w-96 mb-6">
            <input
              type="text"
              placeholder="Rechercher par nom ou prénom"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 pr-4 py-2 bg-white border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500 w-full shadow-sm"
            />
            <SearchIcon className="absolute left-3 top-2.5 text-gray-400" />
          </div>

          {showGroupes ? (
            <div className="mt-4">
              {/* Bouton "Retour" */}
              <button
                onClick={() => setShowGroupes(false)}
                className="bg-blue-500 text-white px-4 py-2 rounded-lg hover:bg-blue-600 transition duration-300 transform hover:scale-105 shadow-lg mb-4"
              >
                <ArrowBackIcon className="mr-2" />
               
              </button>

              <h2 className="text-2xl font-bold mb-2 text-blue-600">Liste des Groupes</h2>
              {groupes.map((groupe) => (
                <div key={groupe.idGroupe} className="border p-4 mb-2 bg-white shadow-md rounded-md transform transition-transform duration-300 hover:scale-102">
                  <h3 className="text-lg font-semibold text-blue-600">{groupe.nomGroupe}</h3>
                  <p>
                    {groupe.etudiants && groupe.etudiants.length > 0
                      ? groupe.etudiants.map((etudiant) => `${etudiant.nom} ${etudiant.prenom}`).join(", ")
                      : "Aucun étudiant dans ce groupe"}
                  </p>
                </div>
              ))}
            </div>
          ) : (
            <div className="bg-white rounded-xl shadow-lg overflow-hidden">
              <div className="max-h-[700px] overflow-y-auto"> {/* Scroll pour la table des étudiants */}
                <table className="w-full">
                  <thead className="bg-gradient-to-r from-blue-500 to-blue-600 sticky top-0">
                    <tr>
                      <th className="p-4 text-left text-white">Étudiants</th>
                      <th className="p-4 text-left text-white">Groupe</th>
                      <th className="p-4 text-left text-white">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {etudiantsTries.map((etudiant, index) => (
                      <tr
                        key={etudiant.idEtudiant}
                        className={`border-b border-gray-100 hover:bg-gray-50 transition ${index % 2 === 0 ? 'bg-gray-50' : 'bg-white'}`}
                      >
                        <td className="p-4 text-gray-800">
                          <input 
                            type="checkbox" 
                            checked={selectedEtudiants.includes(etudiant.idEtudiant)} 
                            onChange={() => toggleSelection(etudiant.idEtudiant)}
                            disabled={etudiant.idGroupe}
                          />
                          {` ${etudiant.nom} ${etudiant.prenom}`}
                        </td>
                        <td className="p-4 text-gray-800">{etudiant.nomGroupe || "-"}</td>
                        <td className="p-4 text-center flex justify-center space-x-3">
                          {etudiant.idGroupe && (
                            <>
                              <Link href={`/users/editgene/${etudiant.idEtudiant}`}>
                                <button className="text-blue-500 hover:text-blue-700 transition duration-200">
                                  <EditIcon />
                                </button>
                              </Link>
                              <button
                                onClick={() => deleteGroupe(etudiant.idGroupe)}
                                className="text-red-500 hover:text-red-700 transition duration-200"
                              >
                                <DeleteIcon />
                              </button>
                            </>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Pagination */}
              <div className="flex justify-between items-center p-4 bg-gradient-to-r from-blue-50 to-gray-50">
                <select
                  onChange={handleItemsPerPageChange}
                  value={itemsPerPage}
                  className="border p-2 rounded-lg shadow-sm"
                >
                  <option value={20}>20 par page</option>
                  <option value={30}>30 par page</option>
                  <option value={50}>50 par page</option>
                </select>
                <div className="flex space-x-2">
                  {Array.from({ length: totalPages }, (_, index) => (
                    <button
                      key={index}
                      onClick={() => paginate(index + 1)}
                      className={`px-4 py-2 text-sm rounded-lg ${currentPage === index + 1 ? 'bg-blue-600 text-white' : 'bg-white text-blue-600'}`}
                    >
                      {index + 1}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}